import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { Refund } from '../../src/entities/refund.entity';
import { buildRefund } from '../factories/refund.factory';
import { Payment } from '../../src/entities/payment.entity';
import { buildPayment } from '../factories/payment.factory';
import { PaymentStatus } from '../../src/enums/payment-status.enum';

describe('Refund Repository', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let paymentId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const paymentEntity = em.create(
      Payment,
      buildPayment(),
    );
    await em.persistAndFlush(paymentEntity);
    paymentId = paymentEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  it('creates and persists an entity', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    const entity = em.create(Refund, data);
    await em.persistAndFlush(entity);
    expect(entity.id).toBeDefined();
  });

  it('retrieves an entity by id', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    const saved = em.create(Refund, data);
    await em.persistAndFlush(saved);
    const found = await em.findOne(Refund, { id: saved.id });
    expect(found).not.toBeNull();
    expect(found!.id).toBe(saved.id);
  });

  it('returns null for non-existent id', async () => {
    const em = orm.em.fork();
    const found = await em.findOne(Refund, {
      id: '00000000-0000-0000-0000-000000000099',
    });
    expect(found).toBeNull();
  });

  it('updates an entity field', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    const saved = em.create(Refund, data);
    await em.persistAndFlush(saved);
    saved.amount = 149.99;
    await em.flush();
    const reloaded = await em.findOne(Refund, { id: saved.id });
    expect(reloaded).not.toBeNull();
    expect(reloaded!.amount).toEqual(saved.amount);
  });

  it('deletes an entity', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    const saved = em.create(Refund, data);
    await em.persistAndFlush(saved);
    await em.removeAndFlush(saved);
    const found = await em.findOne(Refund, { id: saved.id });
    expect(found).toBeNull();
  });

  it('lists all entities', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    await em.persistAndFlush(em.create(Refund, data));
    const all = await em.find(Refund, {});
    expect(all.length).toBeGreaterThanOrEqual(1);
  });

  it('persists with payment foreign key', async () => {
    const em = orm.em.fork();
    const data = buildRefund({ payment: paymentId });
    const saved = em.create(Refund, data);
    await em.persistAndFlush(saved);
    await em.populate(saved, ['payment']);
    expect(saved.payment.id).toBe(paymentId);
  });
});
